// The literal return type retains the same loose row inference the untyped
// Supabase client previously had for `select('*')`; the runtime value is the
// explicit Cloud-schema snapshot above.
export const getSupabaseProjection = (table: string): '*' => {
  const projection = SUPABASE_PROJECTIONS[table];
  if (!projection) throw new Error(`No explicit Supabase projection registered for ${table}`);
  return projection as '*';
};

export const getSupabaseOrderColumns = (table: string): readonly string[] =>
  NON_STANDARD_ORDER_COLUMNS[table] || ['id'];
